\subsection{A completely explicit curve model: the explicit $2$-pushout groupoid $\G_{\Phi,n}$ and the forgetful map $\pi:\GC\to\CB$}\label{subsec:curve-model-clean}

This subsection is expository and is not used later.
Its goal is to make the explicit $2$-pushout
\begin{equation}\label{eq:curve-pushout-clean}
\G_{\Phi,n}\ :=\ \GU\sqcup_{\GX}\GC
\end{equation}
completely concrete in complex dimension~$1$, and to clarify the comparison with the groupoids
in \cite[\S3,\S5]{GualtieriLiPym} and the Kato--Nakayama viewpoint.

\medskip

\medskip

\providecommand{\Cech}{\check{\mathrm C}}

\providecommand{\CB}{\Cech(\mathcal B)}

\subsubsection*{(A) Geometry on a curve and sector boxes on $X^{\log}_n$}

Let $X$ be a connected Riemann surface and let $D=\{p_1,\dots,p_m\}\subset X$ be a reduced finite divisor.
Write $U:=X\setminus D$.
Fix a Kummer level $n\ge 1$ and an irregular type $\Phi$ along $D$ (at level~$n$).
Let $\tau_n:X^{\log}_n\to X$ be the level-$n$ Kato--Nakayama/Kummer map.
Over $U$, $\tau_n$ is a homeomorphism; over each $p_i$ the fiber is the level-$n$ circle of directions
$S^1_{p_i,n}:=\tau_n^{-1}(p_i)$.
Choose pairwise disjoint closed discs $\Delta_i$ around $p_i$ and set $\Delta_i^\times:=\Delta_i\setminus\{p_i\}$.
Let $N_i^\times:=\tau_n^{-1}(\Delta_i^\times)\subset X^{\log}_n$ be the punctured collar near $p_i$.
The Stokes walls at $p_i$ cut $S^1_{p_i,n}$ into finitely many open arcs
\begin{equation}\label{eq:arcs-clean}
S^1_{p_i,n}\setminus\Sigma_{p_i}\ =\ \bigsqcup_{a\in\ZZ/\ell_i\ZZ} I_{i,a},
\end{equation}
and on each arc the Stokes preorder is constant.
Choose \emph{sector boxes}
\begin{equation}\label{eq:boxes-clean}
B_{i,a}\ \subset\ N_i^\times,
\qquad
B_{i,a}\ \simeq\ \Delta_i^\times\times I_{i,a},
\qquad
B_{i,a}\cap B_{i,a+1}\neq\varnothing,
\end{equation}
each contractible, and with overlaps also contractible.
