Let $\St_\Phi$ be the Stokes sheaf on the sector cover (as in Definition~\ref{def:stokes-sheaf}).
Since $B_{i,a}\cap B_{i,a+1}$ is contractible, the group
\begin{equation}\label{eq:stokes-groups-clean}
\St_{i;a,a+1}\ :=\ \St_\Phi(B_{i,a}\cap B_{i,a+1})
\end{equation}
is a constant (typically unipotent) subgroup of the relevant $\Aut(\Gr)$.

\subsubsection*{(B) The three groupoids $\GU,\GX,\GC$ and the \v{C}ech collar groupoid $\CB$}

Fix once and for all the following covers.

\begin{itemize}
\item \textbf{Interior cover on $U$.} Choose a good cover $\mathcal U=\{U_\alpha\}$ of $U$.
Set $\GU:=\Cech(\mathcal U)$.

\item \textbf{Collar cover on $N^\times:=\bigsqcup_i N_i^\times$.}
Set $\mathcal B:=\{B_{i,a}\}_{i,a}$ and define the \emph{plain collar \v{C}ech groupoid}
\begin{equation}\label{eq:CB-def-clean}
\CB\ :=\ \Cech(\mathcal B).
\end{equation}

\item \textbf{Overlap cover.} Consider the overlaps $U_\alpha\cap B_{i,a}\subset U\cap N^\times$ and let
$\mathcal W:=\{W_{\alpha;i,a}\}$ be any refinement by contractible opens.
Set $\GX:=\Cech(\mathcal W)$.
\end{itemize}

Now define the \emph{collar \v{C}ech--Stokes groupoid} $\GC$ as the Stokes decoration of $\CB$:
\begin{equation}\label{eq:GC-objects-clean}
(\GC)_0\ :=\ \bigsqcup_{i,a} B_{i,a},
\end{equation}
and arrows
\begin{equation}\label{eq:GC-arrows-clean}
(\GC)_1\ :=\ \bigsqcup_{i,a,a'}\Bigl((B_{i,a}\cap B_{i,a'})\times \St_\Phi(B_{i,a}\cap B_{i,a'})\Bigr),
\end{equation}
where $(x,u)$ is an arrow from the object $B_{i,a}$ to the object $B_{i,a'}$ (at the point $x$),
and composition is
\begin{equation}\label{eq:GC-comp-clean}
(x,u')\circ(x,u)\ :=\ (x,u'u).
\end{equation}

\medskip

\noindent\textbf{The forgetful projection.}
There is a \emph{strict} functor
\begin{equation}\label{eq:pi-forgetful-clean}
\pi:\GC\longrightarrow \CB
\end{equation}
defined by \emph{forgetting the Stokes decoration}:
on objects it is the identity (same sector boxes), and on arrows
\begin{equation}\label{eq:pi-on-arrows-clean}
\pi(x,u)\ :=\ x \in (B_{i,a}\cap B_{i,a'})\ \subset\ (\CB)_1.
\end{equation}
So here $\CB$ is the \v{C}ech groupoid of the cover $\mathcal B$, \emph{not} $\CC$.

\subsubsection*{(C) The explicit $2$-pushout and its ``generators-and-relations'' meaning}

There are canonical strict functors $j_U:\GX\to\GU$ and $j_C:\GX\to\GC$ induced by inclusions:
on objects, $W_{\alpha;i,a}\subset U_\alpha$ and $W_{\alpha;i,a}\subset B_{i,a}$;
on arrows, overlaps map to the corresponding \v{C}ech arrows, and in $\GC$ we take the
\emph{trivial} Stokes label $u=1$.

\begin{definition} \label{def:curve-pushout-clean}
Define
\begin{equation}\label{eq:pushout-clean}
\G_{\Phi,n}\ :=\ \GU\sqcup_{\GX}\GC.
\end{equation}
\end{definition}

Concretely, $\G_{\Phi,n}$ is obtained from the disjoint union groupoid $\GU\bigsqcup\GC$
by imposing precisely the identifications dictated by $\GX$ (gluing the overlap charts),
while keeping the Stokes-decorated arrows as genuinely new arrows.
Equivalently, $\G_{\Phi,n}$ admits the standard coequalizer presentation
\begin{equation}\label{eq:coeq-clean}
\G_{\Phi,n}\ \cong\ \mathrm{coeq}\Bigl(F(R)\rightrightarrows F(E)\Bigr),
\end{equation}
where $E$ consists of the generating arrows coming from $\GU$ and $\GC$,
and $R$ encodes only the overlap relations from $\GX$.

\subsubsection*{(D) A finite skeleton (graph-of-groupoids picture) on curves}

The \v{C}ech presentation is explicit but indexed by covers.
On a curve one can replace it by a finite skeleton without changing representation theory (Morita reduction).

Fix a basepoint $x_0\in U$.
For each sector box $B_{i,a}$ pick a point $b_{i,a}\in B_{i,a}$ and choose a path class
$\gamma_{i,a}:x_0\to b_{i,a}$ inside $U\cup N^\times$ entering the collar through the sector $I_{i,a}$.

Define a small groupoid $\G^{\mathrm{sk}}_{\Phi,n}$ by:
\begin{itemize}
\item objects: $\{x_0\}\cup\{b_{i,a}\}_{i,a}$;
\item arrows generated by:
  \begin{enumerate}
  \item $\pi_1(U,x_0)$ as loops at $x_0$ (ordinary monodromy),
  \item the spokes $\gamma_{i,a}:x_0\to b_{i,a}$ and formal inverses,
  \item for each fixed $i$ and adjacent sectors $a\to a+1$, arrows
  $\sigma_{i,a}(u):b_{i,a}\to b_{i,a+1}$ for each $u\in \St_{i;a,a+1}$,
  \end{enumerate}
\item relations:
  \begin{enumerate}
  \item $\sigma_{i,a+1}(v)\circ \sigma_{i,a}(u)=\sigma_{i,a}(vu)$ whenever the compositions correspond to the same overlap,
  \item the overlap/gluing relations expressing compatibility between the restriction of monodromy on $U$
  and the boundary Stokes jumps (the same relations encoded by $\GX$),
  \item the usual groupoid relations (identities/inverses).
  \end{enumerate}
\end{itemize}

\begin{proposition}\label{prop:curve-skeleton-clean}
There is a canonical chain of Morita equivalences connecting the cover-based presenter $\G_{\Phi,n}$ and the finite skeletal presenter
$\G^{\mathrm{sk}}_{\Phi,n}$. In particular, they present the same classifying stack, and for every $r\ge 1$ there is a natural equivalence
of groupoids
\begin{equation}\label{eq:repr-clean}
\Rep_r(\G_{\Phi,n})\ \simeq\ \Rep_r(\G^{\mathrm{sk}}_{\Phi,n}).
\end{equation}
\end{proposition}

\begin{proof}
Fix the good cover $\mathcal U=\{U_\alpha\}$ of $U$, the sector-box cover $\mathcal B=\{B_{i,a}\}$ of $N^\times$, and a contractible refinement
$\mathcal W=\{W_{\alpha;i,a}\}$ of the overlap $U\cap N^\times$ as in \Cref{subsec:curve-model-clean}. The global presenter is the explicit $2$-pushout
\begin{equation}\label{eq:curve-pushout-cech}
\G_{\Phi,n}\ :=\ \GU\ \sqcup_{\GX}\ \GC,
\qquad
\GU=\Cech(\mathcal U),\ \GX=\Cech(\mathcal W),\ \GC=\Cech\text{--Stokes}(\mathcal B).
\end{equation}

Choose basepoints $x_\alpha\in U_\alpha$ and $b_{i,a}\in B_{i,a}$, and choose basepoints in each $W_{\alpha;i,a}$ compatibly with the inclusions
$W_{\alpha;i,a}\subset U_\alpha$ and $W_{\alpha;i,a}\subset B_{i,a}$.
Since all charts and all nonempty finite intersections are contractible, each connected overlap carries a unique homotopy class of paths between the
chosen basepoints. Therefore each \v{C}ech presenter admits the standard Morita reduction to a small groupoid with one object per chart and one arrow
per nonempty overlap:
\begin{equation}\label{eq:morita-reductions}
\GU\ \simeq_{\mathrm{Morita}}\ \GU^{\mathrm{bp}},
\qquad
\GX\ \simeq_{\mathrm{Morita}}\ \GX^{\mathrm{bp}},
\qquad
\GC\ \simeq_{\mathrm{Morita}}\ \GC^{\mathrm{bp}}.
\end{equation}
Moreover, the refinement functors $j_U:\GX\to\GU$ and $j_C:\GX\to\GC$ induce functors
$j_U^{\mathrm{bp}}:\GX^{\mathrm{bp}}\to\GU^{\mathrm{bp}}$ and $j_C^{\mathrm{bp}}:\GX^{\mathrm{bp}}\to\GC^{\mathrm{bp}}$, compatible with
\eqref{eq:morita-reductions}. Taking explicit $2$-pushouts (realized by Lemma~\ref{lem:strict-pushout-is-bicategorical}) and using the $2$-pushout universal property yields a comparison functor between the two pushouts, unique up to unique isomorphism. This comparison is a Morita equivalence, hence a canonical chain
\begin{equation}\label{eq:morita-chain-curve}
\G_{\Phi,n}=\GU\sqcup_{\GX}\GC\ \simeq_{\mathrm{Morita}}\ \GU^{\mathrm{bp}}\sqcup_{\GX^{\mathrm{bp}}}\GC^{\mathrm{bp}}
=: \G^{\mathrm{bp}}_{\Phi,n}.
\end{equation}
This passage is summarized by Diagram~\eqref{eq:curve-morita-cube} below.

Finally, by construction the reduced pushout $\G^{\mathrm{bp}}_{\Phi,n}$ is the explicit finite skeleton
$\G^{\mathrm{sk}}_{\Phi,n}$ introduced in \Cref{subsec:curve-model-clean}: it has objects $x_0$ and the sector basepoints $b_{i,a}$, and it is
generated by ordinary monodromy in $U$ together with the Stokes-labelled arrows between adjacent sectors, modulo the overlap relations coming from
$\GX$. Thus $\G^{\mathrm{bp}}_{\Phi,n}\cong \G^{\mathrm{sk}}_{\Phi,n}$. Applying $\Rep_r(-)$, which is invariant under Morita equivalence of
presenters, yields \eqref{eq:repr-clean}.

\begin{equation}\label{eq:curve-morita-cube}
\begin{tikzcd}[row sep=large, column sep=large]
\GU
\arrow[d, "\simeq_{\mathrm{Morita}}" description]
\arrow[rrr, bend left=18, "i_U"]
&
\GX
\arrow[l, "j_U"']
\arrow[r, "j_C"]
\arrow[d, "\simeq_{\mathrm{Morita}}" description]
&
\GC
\arrow[d, "\simeq_{\mathrm{Morita}}" description]
\arrow[r, "i_C"]
&
\GU \sqcup_{\GX} \GC
\arrow[d, "\simeq_{\mathrm{Morita}}" description]
\\
\GU^{\mathrm{bp}}
\arrow[rrr, bend right=18, "i_U^{\mathrm{bp}}"']
&
\GX^{\mathrm{bp}}
\arrow[l, "j_U^{\mathrm{bp}}"']
\arrow[r, "j_C^{\mathrm{bp}}"]
&
\GC^{\mathrm{bp}}
\arrow[r, "i_C^{\mathrm{bp}}"]
&
\GU^{\mathrm{bp}} \sqcup_{\GX^{\mathrm{bp}}} \GC^{\mathrm{bp}}
\arrow[d, "\cong"]
\\
&&&
\G^{\mathrm{sk}}_{\Phi,n}.
\end{tikzcd}
\end{equation}
\end{proof}

